/** Shared language registry. Selecting a language never changes the mystery. */
export const SUPPORTED_LOCALES = ['en', 'ko', 'es', 'fr', 'de', 'pt', 'ja', 'zh', 'ar', 'hi'] as const;
export type Locale = (typeof SUPPORTED_LOCALES)[number];
export const DEFAULT_LOCALE: Locale = 'en';
export const LOCALES: ReadonlyArray<{ code: Locale; name: string; dir: 'ltr' | 'rtl' }> = [
  { code: 'en', name: 'English', dir: 'ltr' },
  { code: 'ko', name: '한국어', dir: 'ltr' },
  { code: 'es', name: 'Español', dir: 'ltr' },
  { code: 'fr', name: 'Français', dir: 'ltr' },
  { code: 'de', name: 'Deutsch', dir: 'ltr' },
  { code: 'pt', name: 'Português', dir: 'ltr' },
  { code: 'ja', name: '日本語', dir: 'ltr' },
  { code: 'zh', name: '简体中文', dir: 'ltr' },
  { code: 'ar', name: 'العربية', dir: 'rtl' },
  { code: 'hi', name: 'हिन्दी', dir: 'ltr' },
];
export function isLocale(value: unknown): value is Locale {
  return typeof value === 'string' && (SUPPORTED_LOCALES as readonly string[]).includes(value);
}
export function getDirection(locale: Locale): 'ltr' | 'rtl' { return locale === 'ar' ? 'rtl' : 'ltr'; }

/**
 * detective-voice.ts — Stage-scoped guidance copy for the DetectiveAside component.
 *
 * Authored by Kiro (2026-10-31).
 *
 * This module is a pure data/logic layer with no React, DOM, randomness, solver,
 * case, suspect, answer, server, storage, or AI dependency. The selection depends
 * only on locale and stage.
 *
 * Attribution note: The inherited application (engine, Game.tsx, CSS, server routes)
 * is Codex work. The hypothesis board (hypothesis.ts, HypothesisBoard.tsx, related
 * specs) is prior Kiro CLI work. This module and DetectiveAside.tsx are new Kiro work.
 */

import type { Locale } from '@/lib/game/types';

// ---------------------------------------------------------------------------
// Stage type
// ---------------------------------------------------------------------------

/** The six investigative stages that the aside tracks. */
export type DetectiveStage =
  | 'casting'
  | 'awakening'
  | 'listening'
  | 'confronting'
  | 'deducing'
  | 'reveal';

// ---------------------------------------------------------------------------
// Copy record
// ---------------------------------------------------------------------------

/**
 * A single stage's localized guidance line.
 * Readonly so consumers cannot accidentally mutate the shared static copy object.
 */
export type StageCopy = Readonly<{
  /** Short instruction, ~1–2 sentences, ≤ 25 English words. */
  line: string;
}>;

/** Full bilingual copy for one stage. */
type BilingualStageCopy = {
  ko: StageCopy;
  en: StageCopy;
};

/**
 * All twelve stage lines (six stages × two locales).
 *
 * English: idiomatic, dry, warm domestic-detective humor.
 * Korean: natural localization — not a word-for-word translation.
 *
 * No line invents evidence, suspects a particular object, references guilt,
 * describes a motive, or reacts differently based on accusation outcome.
 * The three code-owned official statements remain the only logical evidence.
 */
const VOICE_COPY: Record<DetectiveStage, BilingualStageCopy> = {
  casting: {
    ko: {
      line: '사진 속 물건 셋을 골라 눈을 붙여 주세요. 탐정의 첫 번째 임무는 용의자 확보입니다.',
    },
    en: {
      line: 'Pick three objects and place their faces. Every good case starts with a proper suspect list.',
    },
  },
  awakening: {
    ko: {
      line: '방이 깨어나는 중입니다. 아직 아무것도 할 필요 없어요 — 지켜만 보세요.',
    },
    en: {
      line: "Give them a moment. Waking up is hard enough without being immediately questioned.",
    },
  },
  listening: {
    ko: {
      line: '세 물건의 공식 증언을 모두 들어 주세요. 이 세 마디가 이번 사건의 증거 전부입니다.',
    },
    en: {
      line: 'Hear all three official statements. Those three statements are the only evidence in this case.',
    },
  },
  confronting: {
    ko: {
      line: '각 물건을 추궁하면 다른 물건이 반론합니다. 두 인용문을 나란히 놓고 직접 메모해 두세요.',
    },
    en: {
      line: "Question each object — another will object. Compare the two quoted statements side by side and note what you find.",
    },
  },
  deducing: {
    ko: {
      line: '맞지 않는 가설을 눌러 지우고, 다시 누르면 되살릴 수 있어요. 지목은 딱 한 번이니 신중하게.',
    },
    en: {
      line: 'Cross out hypotheses that don\'t fit — tap again to restore any. Your accusation is one-time only, so take your time.',
    },
  },
  reveal: {
    ko: {
      line: '사건이 마무리됐습니다. 해설을 읽으면 세 증언이 어떻게 이어지는지 확인할 수 있어요.',
    },
    en: {
      line: "Case closed. Read the explanation to see how the three statements fit together.",
    },
  },
};

// ---------------------------------------------------------------------------
// Accessor
// ---------------------------------------------------------------------------

/**
 * Returns the localized guidance copy for the given stage and locale.
 *
 * Deterministic: the same (stage, locale) pair always yields the same copy.
 * No randomness, no external I/O.
 */
export function getDetectiveVoice(stage: DetectiveStage, locale: Locale): StageCopy {
  return VOICE_COPY[stage][locale];
}

'use client';

import { useRef, useState } from 'react';
import type { Locale, PublicSnapshot, SuspectId } from '@/lib/game';

type Props = {
  snapshot: PublicSnapshot;
  locale: Locale;
  completed: SuspectId[];
  onComplete: (id: SuspectId) => void;
  onSpeak: (id: SuspectId, line: string) => void;
};

/** Scripted cross-examination quotes the frozen official claims; it never judges a theory. */
export default function CrossExamination({ snapshot, locale, completed, onComplete, onSpeak }: Props) {
  const [selected, setSelected] = useState<SuspectId>();
  const [turn, setTurn] = useState(0);
  const [theories, setTheories] = useState<Partial<Record<SuspectId, string>>>({});
  const exchangeRef = useRef<HTMLDivElement>(null);
  const ko = locale === 'ko';
  const t = (a: string, b: string) => ko ? a : b;
  const routes = snapshot.interrogations;
  if (!routes) return null;
  const route = selected ? routes[selected] : undefined;
  const name = (id: SuspectId) => snapshot.suspects.find(s => s.id === id)?.displayName ?? id;
  function question(id: SuspectId) {
    setSelected(id); setTurn(0);
    onSpeak(id, routes![id].challenge);
    requestAnimationFrame(() => exchangeRef.current?.focus());
  }
  return <section className="cross-examination" aria-labelledby="cross-title">
    <div className="evidence-title"><h2 id="cross-title">{t('잠깐, 말이 안 맞는데?', 'Wait. That doesn’t add up.')}</h2><span data-testid="exam-progress">{completed.length}/3</span></div>
    <p className="cross-intro">{t('진술을 물고 늘어져 보세요. 다른 물건도 가만있지 않을걸요.', 'Press them on their statements. The others won’t stay quiet.')}</p>
    <div className="question-list">{snapshot.suspects.map((suspect, i) => <button key={suspect.id} data-testid={`question-${suspect.id}`} aria-pressed={selected === suspect.id} onClick={() => question(suspect.id)}>
      <span className="question-number">{i + 1}</span><span><strong>{suspect.displayName}</strong><span>{routes[suspect.id].question}</span></span><span className="question-status">{completed.includes(suspect.id) ? '✓' : '?'}</span>
    </button>)}</div>
    {route && <div className="exchange" ref={exchangeRef} tabIndex={-1} data-testid="exchange" aria-label={t('대질 대화', 'Cross-examination dialogue')}>
      <p className="detective-question"><b>{t('킬록 홈즈', 'Kirock Homes')}</b>{route.question}</p>
      <div className="dialogue-turn"><span>{name(route.speakerId)}</span><p>{route.challenge}</p></div>
      {turn === 0 ? <button className="rebuttal-button" data-testid="hear-rebuttal" onClick={() => { setTurn(1); onSpeak(route.rebuttalSpeakerId, route.rebuttal); }}>{t(`${name(route.rebuttalSpeakerId)}의 반론 듣기`, `Hear ${name(route.rebuttalSpeakerId)}’s objection`)} <span aria-hidden="true">!</span></button> : <>
        <div className="dialogue-turn objection" aria-live="polite"><span>{name(route.rebuttalSpeakerId)} <b>{t('이의 있어!', 'Objection!')}</b></span><p>{route.rebuttal}</p></div>
        <div className="citation-strip"><b>{t('대조할 공식 증언', 'Compare the official statements')}</b>{route.citedStatementIds.map(id => { const statement = snapshot.statements.find(s => s.id === id)!; return <blockquote key={id}><cite>{name(statement.speakerId)}</cite>{statement.text}</blockquote>; })}</div>
        <div className="detective-note"><b>{t('추리 노트', 'Detective’s note')}</b><p>{route.note}</p></div>
        {turn < 2 ? <button className="secondary" data-testid="save-note" onClick={() => { setTurn(2); onComplete(route.speakerId); }}>{t('노트에 남기기', 'Pin this comparison')} <span aria-hidden="true">＋</span></button> : <p className="note-saved" role="status">✓ {t(completed.length === 3 ? '세 대질을 마쳤어요. 이제 당신의 추리를 정리하세요.' : '노트에 남겼어요. 다른 물건도 추궁해 보세요.', completed.length === 3 ? 'All three confrontations are complete. Time for your theory.' : 'Pinned. Question another object.')}</p>}
      </>}
      <small className="dialogue-rule">{t('대질은 세 공식 증언을 비교하는 대화입니다. 새 증거가 추가되지는 않아요.', 'The conversation compares the three official statements. It adds no new evidence.')}</small>
    </div>}
    {completed.length > 0 && <details className="notebook" open={completed.length === 3}>
      <summary>{t('내 추리 수첩', 'My detective notebook')} <span>{completed.length}/3</span></summary>
      <p>{t('어느 말이 수상한가요? 메모는 언제든 바꿀 수 있고 정답을 알려주지는 않아요.', 'Which claim feels suspicious? These are your notes, not a verdict. Change them any time.')}</p>
      {snapshot.suspects.filter(s => completed.includes(s.id)).map(s => <div className="theory-row" key={s.id}>
        <label htmlFor={`theory-${s.id}`}>{s.displayName}</label><select id={`theory-${s.id}`} value={theories[s.id] ?? ''} onChange={e => setTheories(v => ({ ...v, [s.id]: e.target.value }))}><option value="">{t('아직 보류', 'Undecided')}</option><option value="true">{t('참인 것 같아', 'I think it’s true')}</option><option value="false">{t('거짓인 것 같아', 'I think it’s false')}</option></select>
      </div>)}
    </details>}
  </section>;
}

'use client';

/**
 * HypothesisBoard.tsx — Player-owned manual deduction scratchpad.
 *
 * This component is Kiro work (2026-10-31). It is a pure client component with
 * local state only. It never reads the solver, case draft, role assignment, or
 * culprit identity. All eliminations are manual player decisions.
 *
 * The inherited application code (Game.tsx, CrossExamination.tsx, CSS, engine)
 * is Codex work. Codex is responsible for rendering this component and styling
 * the hypothesis-board / hypothesis-grid / hypothesis-card class names.
 */

import { useState } from 'react';
import { buildHypotheses, type Hypothesis, type HypothesisId } from '@/lib/game/hypothesis';
import type { Locale, Suspect, SuspectId } from '@/lib/game/types';

type Props = {
  suspects: readonly Suspect[];
  locale: Locale;
  /** factLabels[0] = label for fact=false event; factLabels[1] = label for fact=true event. */
  factLabels: readonly [string, string];
};

/** Inline localizer — same pattern as CrossExamination.tsx. */
function useT(locale: Locale) {
  return (ko: string, en: string) => locale === 'ko' ? ko : en;
}

/**
 * Manual six-world hypothesis board.
 *
 * Renders six toggleable cards representing every (culpritId × fact) world.
 * The player eliminates worlds they consider impossible; the board never
 * auto-eliminates or reveals which world is correct.
 */
export default function HypothesisBoard({ suspects, locale, factLabels }: Props) {
  const t = useT(locale);

  // Derive display order from the suspects array (mirrors publicSnapshot ordering).
  const displayOrder: SuspectId[] = suspects.map((s) => s.id as SuspectId);
  const hypotheses: Hypothesis[] = buildHypotheses(suspects, displayOrder);

  // Set of eliminated hypothesis IDs; never mutated — always replaced with a new Set.
  const [eliminated, setEliminated] = useState<Set<HypothesisId>>(new Set());

  function toggle(id: HypothesisId) {
    setEliminated((prev) => {
      const next = new Set(prev);
      if (next.has(id)) {
        next.delete(id);
      } else {
        next.add(id);
      }
      return next;
    });
  }

  function reset() {
    setEliminated(new Set());
  }

  const total = hypotheses.length;             // always 6
  const remaining = total - eliminated.size;

  // The one remaining card — only meaningful when exactly one is left.
  const lastCard: Hypothesis | undefined =
    remaining === 1 ? hypotheses.find((h) => !eliminated.has(h.id)) : undefined;

  return (
    <section
      className="hypothesis-board"
      data-testid="hypothesis-board"
      aria-label={t('가설 보드', 'Hypothesis board')}
    >
      <h2>{t('내 가설 보드', 'My hypothesis board')}</h2>

      <p className="hypothesis-instruction">
        {t(
          '세 증언과 맞지 않는 가설을 눌러 지워 보세요. 다시 누르면 되돌릴 수 있어요.',
          'Tap the theories that don\'t fit the three statements to cross them out. Tap again to restore them.',
        )}
      </p>

      {/* Remaining count */}
      <p className="hypothesis-count" aria-live="polite">
        {t(`남은 가설: ${remaining} / ${total}`, `Remaining: ${remaining} / ${total}`)}
        {remaining === 1 && lastCard && (
          <>
            {' — '}
            <strong>{t('내가 남긴 가설', 'My remaining theory')}</strong>
          </>
        )}
      </p>

      {/* Zero-remaining message */}
      {remaining === 0 && (
        <p className="hypothesis-empty" role="status">
          {t(
            '모든 가설을 제외했어요. 초기화 버튼으로 다시 시작할 수 있어요.',
            'All hypotheses eliminated. Use the reset button to restore the cards.',
          )}
        </p>
      )}

      <div className="hypothesis-grid">
        {hypotheses.map((h) => {
          const isEliminated = eliminated.has(h.id);
          const factLabel = h.fact ? factLabels[1] : factLabels[0];
          const statusText = isEliminated
            ? t('제외됨', 'Eliminated')
            : t('가능', 'Possible');
          const isLast = lastCard?.id === h.id;

          return (
            <button
              key={h.id}
              className="hypothesis-card"
              data-testid={`hypothesis-card-${h.id}`}
              aria-pressed={isEliminated}
              onClick={() => toggle(h.id)}
              type="button"
            >
              <span className="hypothesis-suspect">{h.suspectDisplayName}</span>
              <span className="hypothesis-fact">{factLabel}</span>
              <span className="hypothesis-status">{statusText}</span>
              {isLast && (
                <span className="hypothesis-last-label">
                  {t('내가 남긴 가설', 'My remaining theory')}
                </span>
              )}
            </button>
          );
        })}
      </div>

      <button
        className="hypothesis-reset"
        data-testid="hypothesis-reset"
        onClick={reset}
        type="button"
      >
        {t('가설 초기화', 'Reset hypotheses')}
      </button>
    </section>
  );
}

'use client';

/**
 * DetectiveAside.tsx — Stage-contextual guidance panel for Kirock Homes.
 *
 * Authored by Kiro (2026-10-31).
 *
 * A compact, purely presentational aside that pairs the /art/kirolock-homes.png
 * mascot image (72 × 72, decorative) with stage-scoped detective guidance.
 * Receives stage and locale as props; holds no state and makes no network requests.
 *
 * The notebook title is rendered as <strong class="detective-aside-title"> rather
 * than a heading element, so Codex retains full control of the document outline.
 *
 * Class names (detective-aside, detective-aside-mascot, detective-aside-copy,
 * detective-aside-title, detective-aside-line) and the data-testid/data-stage
 * attributes are defined here; all styling is Codex's responsibility.
 *
 * The image filename /art/kirolock-homes.png is intentionally historical and does
 * not reflect the current "Kirock" brand spelling — it is not an error to fix.
 *
 * Attribution note: The inherited application (engine, Game.tsx, CSS, server routes,
 * CrossExamination.tsx) is Codex work. The hypothesis board module and component are
 * prior Kiro CLI work. This component and detective-voice.ts are new Kiro work.
 */

import { getDetectiveVoice, type DetectiveStage } from '@/lib/ui/detective-voice';
import type { Locale } from '@/lib/game/types';

// Re-export so consumers can import the stage type from this file if preferred.
export type { DetectiveStage };

// ---------------------------------------------------------------------------
// Props
// ---------------------------------------------------------------------------

export type DetectiveAsideProps = {
  stage: DetectiveStage;
  locale: Locale;
};

// ---------------------------------------------------------------------------
// Heading constants
// ---------------------------------------------------------------------------

const HEADING: Record<Locale, string> = {
  en: "Kirock's notebook",
  ko: '킬록의 수첩',
};

// ---------------------------------------------------------------------------
// Component
// ---------------------------------------------------------------------------

/**
 * DetectiveAside
 *
 * Renders a compact aside with:
 *   - The Kirock Homes mascot image (decorative, empty alt, aria-hidden, 72 × 72)
 *   - A notebook title as <strong> ("Kirock's notebook" / "킬록의 수첩")
 *   - A short stage guidance line
 *
 * No correct/incorrect, guilt, suspect identity, case data, statement content,
 * solver, or private-answer information is accepted or displayed.
 *
 * The `data-stage` attribute on the aside element helps browser verification
 * confirm the active stage without inspecting copy text.
 */
export default function DetectiveAside({ stage, locale }: DetectiveAsideProps) {
  const copy = getDetectiveVoice(stage, locale);
  const heading = HEADING[locale];

  return (
    <aside
      className="detective-aside"
      data-testid="detective-aside"
      data-stage={stage}
      aria-label={heading}
    >
      {/*
        Decorative mascot image.
        - alt="" marks it as decorative for screen readers.
        - aria-hidden="true" prevents the empty alt from creating a redundant
          focusable element in some AT implementations.
        - Explicit width/height prevent layout shift (CLS).
        - The filename kirolock-homes.png is historical; see file header note.
      */}
      <img
        className="detective-aside-mascot"
        src="/art/kirolock-homes.png"
        alt=""
        aria-hidden="true"
        width={72}
        height={72}
        decoding="async"
      />

      <div className="detective-aside-copy">
        {/*
          Notebook title rendered as <strong> rather than a heading element,
          per Codex integration guidance. This avoids introducing a heading
          into the document outline that Codex cannot control from Game.tsx.
          The <aside>'s aria-label already identifies the region for AT.
        */}
        <strong className="detective-aside-title">{heading}</strong>

        {/*
          Stage guidance line.
          Not a live region: the aside updates as the player moves between
          phases, but changes are driven by deliberate player navigation rather
          than background activity, so aria-live would announce unnecessarily.
          Codex may add role="status" if integration evidence shows a need.
        */}
        <p className="detective-aside-line">{copy.line}</p>
      </div>
    </aside>
  );
}

/** The engine has no DOM, network, AI, storage, or framework dependencies. */
import type { Locale } from "../i18n/locales";
export type { Locale } from "../i18n/locales";
export const SUSPECT_IDS = ["s0", "s1", "s2"] as const;
export type SuspectId = (typeof SUSPECT_IDS)[number];
export const OBJECT_KINDS = ["cup", "lamp", "electronics", "book", "plant", "toy", "other"] as const;
export type ObjectKind = (typeof OBJECT_KINDS)[number];
export const PERSONALITY_IDS = ["dry", "dramatic", "sleepy", "cheerful"] as const;
export type PersonalityId = (typeof PERSONALITY_IDS)[number];
export type StoryId = "coffee" | "sticker";

export type Claim =
  | { type: "culprit_is"; suspectId: SuspectId }
  | { type: "fact_is"; value: boolean };
export type World = { culpritId: SuspectId; fact: boolean };
export type Statement = { id: string; speakerId: SuspectId; claim: Claim };
export type Suspect = {
  id: SuspectId;
  displayName: string;
  /** Localizable sample identity only; remove this marker when the player renames it. */
  sampleName?: "cup" | "lamp" | "keyboard";
  kind: string;
  face: { x: number; y: number; scale: number; rotation: number };
  personalityId: string;
};
export type Triple<T> = [T, T, T];
export type RoleAssignment = { a: SuspectId; b: SuspectId; c: SuspectId };
export type CaseDraft = {
  schemaVersion: 1;
  templateId: "opposed-facts";
  templateVersion: 1;
  storyId: StoryId;
  storyVersion: 1;
  factId: "lamp-on-at-spill" | "bell-after-midnight";
  factSubjectId?: SuspectId;
  roleAssignment: RoleAssignment;
  factInverted: boolean;
  displayOrder: Triple<SuspectId>;
  locale: Locale;
  suspects: Triple<Suspect>;
  statements: Triple<Statement>;
};
export type PublicStatement = { id: string; speakerId: SuspectId; text: string };
export type PublicSnapshot = {
  locale: Locale;
  title: string;
  context: string;
  suspects: Suspect[];
  statements: PublicStatement[];
  characterLines: Record<SuspectId, string[]>;
  /** Optional only for immutable shares created before the interrogation expansion. */
  interrogations?: import('./interrogation').Interrogations;
  /** Public event alternatives, ordered false then true; neither is marked correct. */
  factLabels?: [string, string];
};
export type CaseResolution = {
  correct: boolean;
  accusedId: SuspectId;
  culpritId: SuspectId;
  proofSteps: string[];
  confession: string;
  fact: boolean;
};

{
  "name": "room-of-suspects",
  "version": "1.0.0",
  "private": true,
  "engines": {
    "node": ">=22.13.0"
  },
  "scripts": {
    "dev": "next dev --hostname 127.0.0.1",
    "build": "next build",
    "start": "next start --hostname 127.0.0.1",
    "typecheck": "next typegen && tsc --noEmit",
    "test": "node --import tsx --conditions=react-server --test tests/*.test.ts",
    "test:e2e": "playwright test",
    "cleanup": "node --env-file-if-exists=.env.local --import tsx --conditions=react-server scripts/cleanup.ts",
    "package": "node scripts/package.mjs"
  },
  "dependencies": {
    "next": "16.4.3",
    "react": "19.3.1",
    "react-dom": "19.3.1",
    "server-only": "0.0.1",
    "sharp": "0.35.5"
  },
  "devDependencies": {
    "typescript": "5.9.3",
    "@types/node": "^24.0.0",
    "@types/react": "^19.0.0",
    "@types/react-dom": "^19.0.0",
    "tsx": "4.23.15",
    "@playwright/test": "1.64.1"
  }
}

{
  "compilerOptions": {
    "target": "ES2022", "lib": ["dom", "dom.iterable", "esnext"],
    "allowJs": true, "skipLibCheck": true, "strict": true, "noEmit": true,
    "esModuleInterop": true, "module": "esnext", "moduleResolution": "bundler",
    "resolveJsonModule": true, "isolatedModules": true, "jsx": "react-jsx",
    "incremental": true, "plugins": [{"name":"next"}],
