  const en = getDetectiveVoice('reveal', 'en');
  for (const word of forbiddenEn) {
    assert.ok(
      !en.line.toLowerCase().includes(word),
      `en reveal line contains forbidden word "${word}": ${en.line}`,
    );
  }
});

